<template><section><header class="page-head"><div><p class="eyebrow">PAYMENT</p><h2>费用缴纳</h2><p>支付宝沙箱模拟支付，不产生真实扣款。</p></div></header><div class="payment-list"><PaymentItem v-for="v in items" :key="v.id" :payment="v" @pay="pay"/><EmptyState v-if="!items.length"/></div></section></template><script setup lang="ts">import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{listPayments,payPayment}from'../api/payment';import type{Payment}from'../types';import PaymentItem from'../components/common/PaymentItem.vue';import EmptyState from'../components/common/EmptyState.vue';const items=ref<Payment[]>([]);async function load(){items.value=await listPayments()}async function pay(id:number){try{await payPayment(id);ElMessage.success('支付宝沙箱支付成功');load()}catch(e){ElMessage.error((e as Error).message)}}onMounted(load)</script>
